import React, { useEffect, useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import axios from 'axios';

const RepoDetails = () => {
  const { repoName } = useParams();
  const navigate = useNavigate();

  const [repo, setRepo] = useState(null);
  const [lineCount, setLineCount] = useState(0);

  useEffect(() => {
    axios.get('http://localhost:5000/api/user', { withCredentials: true })
      .then(res => {
        const provider = res.data.user.provider || 'github';
        
        axios.get(`http://localhost:5000/api/${provider}/repos`, { withCredentials: true })
          .then(res => {
            const foundRepo = res.data.find(r => r.name === repoName);
            if (foundRepo) {
              setRepo({ ...foundRepo, provider });

              // Call lines API
              axios.get(`http://localhost:5000/api/repo/lines?repo=${repoName}&provider=${provider}`, { withCredentials: true })
                .then(lineRes => setLineCount(lineRes.data.lines || 0));
            }
          });
      })
      .catch(err => console.error("Error:", err));
  }, [repoName]);

  if (!repo) return <p>Loading repo info...</p>;

  return (
    <div style={{ padding: '2rem' }}>
      <button onClick={() => navigate(-1)}>← Back</button>
      <h2>Repo: {repoName}</h2>
      <p><strong>Auto Review:</strong> Enabled</p>
      <p><strong>⭐ Stars:</strong> {repo.stars}</p>
      <p><strong>Default Branch:</strong> {repo.default_branch}</p>
      <p><strong># of lines in default branch:</strong> {lineCount}</p>
    </div>
  );
};

export default RepoDetails;
